import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
   .version 8.1
   .target sm_89
   .address_size 64
   .shared .align 4 .b8 s_partials[1024];
   .visible .entry sdp_attn_kernel(
       .param .u64 Q_ptr,
       .param .u64 K_ptr,
       .param .u64 V_ptr,
       .param .u64 O_ptr,
       .param .u32 B,
       .param .u32 H,
       .param .u32 S,
       .param .u32 D
   )
   {
       .reg .pred p_exit, p0, p1, p2, p_tmp;
       .reg .u32 rB, rH, rS, rD;
       .reg .u64 Q, K, V, O;
       .reg .u32 bx, by, bz, tid, bdim;
       .reg .u32 tmp32, row_idx, base_bh, base_bhS;
       .reg .u64 q_row_bytes, o_row_bytes;
       .reg .u64 addr, addr2;
       .reg .f32 q0, q1, q2, q3;
       .reg .f32 part, kval;
        .reg .f32 dot, scale, invln2, neg_inf, maxv, w, delta, denom, fD;
        .reg .f16 htmp;
        .reg .b16 hbits;
        .reg .u32 d0, d1, d2, d3;
        .reg .u32 j, stride;
        .reg .u64 sbase;
        .reg .f32 out0, out1, out2, out3;
        .reg .u32 lane, wid, fullmask, eightmask;
        .reg .b32 bpart, btmp;
        ld.param.u64 Q, [Q_ptr];
        ld.param.u64 K, [K_ptr];
        ld.param.u64 V, [V_ptr];
        ld.param.u64 O, [O_ptr];
        cvta.to.global.u64 Q, Q;
        cvta.to.global.u64 K, K;
        cvta.to.global.u64 V, V;
        cvta.to.global.u64 O, O;
        ld.param.u32 rB, [B];
        ld.param.u32 rH, [H];
        ld.param.u32 rS, [S];
        ld.param.u32 rD, [D];
        mov.u32 bx, %ctaid.x;
        mov.u32 by, %ctaid.y;
        mov.u32 bz, %ctaid.z;
        mov.u32 tid, %tid.x;
        mov.u32 bdim, %ntid.x;
        setp.ge.u32 p0, bx, rS;
        setp.ge.u32 p1, by, rH;
        setp.ge.u32 p2, bz, rB;
        or.pred p_tmp, p0, p1;
        or.pred p_exit, p_tmp, p2;
        @p_exit bra DONE;
          mov.u64 sbase, s_partials;
         cvt.rn.f32.u32 fD, rD;
          rsqrt.approx.f32 scale, fD;
        mov.f32 invln2, 1.442695;
        mov.f32 neg_inf, -3.402823466e38;
        mad.lo.u32 base_bh, bz, rH, by;
        mul.lo.u32 base_bhS, base_bh, rS;
        add.u32 row_idx, base_bhS, bx;
        mul.wide.u32 addr, row_idx, rD;
        shl.b64 addr, addr, 1;
        add.u64 q_row_bytes, Q, addr;
        add.u64 o_row_bytes, O, addr;
        // lane/warp ids and shuffle masks
        and.b32 lane, tid, 31;
        shr.u32 wid, tid, 5;
        mov.u32 fullmask, 0xffffffff;
        mov.u32 eightmask, 255;
        // Load Q tile into registers
        mov.u32 d0, tid;
        setp.ge.u32 p0, d0, rD;
        @p0 mov.f32 q0, 0.0;
        @!p0 mul.wide.u32 addr2, d0, 2;
        @!p0 add.u64 addr2, q_row_bytes, addr2;
        @!p0 ld.global.b16 hbits, [addr2];
        @!p0 mov.b16 htmp, hbits;
        @!p0 cvt.f32.f16 q0, htmp;
        add.u32 d1, tid, bdim;
        setp.ge.u32 p0, d1, rD;
        @p0 mov.f32 q1, 0.0;
        @!p0 mul.wide.u32 addr2, d1, 2;
        @!p0 add.u64 addr2, q_row_bytes, addr2;
        @!p0 ld.global.b16 hbits, [addr2];
        @!p0 mov.b16 htmp, hbits;
        @!p0 cvt.f32.f16 q1, htmp;
        add.u32 d2, d1, bdim;
        setp.ge.u32 p0, d2, rD;
        @p0 mov.f32 q2, 0.0;
        @!p0 mul.wide.u32 addr2, d2, 2;
        @!p0 add.u64 addr2, q_row_bytes, addr2;
        @!p0 ld.global.b16 hbits, [addr2];
        @!p0 mov.b16 htmp, hbits;
        @!p0 cvt.f32.f16 q2, htmp;
        add.u32 d3, d2, bdim;
        setp.ge.u32 p0, d3, rD;
        @p0 mov.f32 q3, 0.0;
        @!p0 mul.wide.u32 addr2, d3, 2;
        @!p0 add.u64 addr2, q_row_bytes, addr2;
        @!p0 ld.global.b16 hbits, [addr2];
        @!p0 mov.b16 htmp, hbits;
        @!p0 cvt.f32.f16 q3, htmp;
        // Initialize streaming softmax accumulators
        mov.f32 maxv, neg_inf;
        mov.f32 denom, 0.0;
        mov.f32 out0, 0.0;
        mov.f32 out1, 0.0;
        mov.f32 out2, 0.0;
        mov.f32 out3, 0.0;
        mov.u32 j, 0;
    ONEPASS_J_LOOP:
        setp.ge.u32 p0, j, rS;
        @p0 bra ONEPASS_DONE;
        // Load K[j] row base
        add.u32 tmp32, base_bhS, j;
        mul.wide.u32 addr, tmp32, rD;
        shl.b64 addr, addr, 1;
        add.u64 addr, K, addr;
        // compute partial dot q * K[j] for this thread
        mov.f32 part, 0.0;
        setp.ge.u32 p0, d0, rD;
        @p0 bra SKIP_K0_OP;
            mul.wide.u32 addr2, d0, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            fma.rn.f32 part, q0, kval, part;
    SKIP_K0_OP:
        setp.ge.u32 p0, d1, rD;
        @p0 bra SKIP_K1_OP;
            mul.wide.u32 addr2, d1, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            fma.rn.f32 part, q1, kval, part;
    SKIP_K1_OP:
        setp.ge.u32 p0, d2, rD;
        @p0 bra SKIP_K2_OP;
            mul.wide.u32 addr2, d2, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            fma.rn.f32 part, q2, kval, part;
    SKIP_K2_OP:
        setp.ge.u32 p0, d3, rD;
        @p0 bra SKIP_K3_OP;
            mul.wide.u32 addr2, d3, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            fma.rn.f32 part, q3, kval, part;
    SKIP_K3_OP:
        // Warp-level reduction
        mov.b32 bpart, part;
        shfl.sync.down.b32 btmp, bpart, 16, 31, fullmask;
        mov.b32 dot, btmp;
        add.rn.f32 part, part, dot;
        mov.b32 bpart, part;
        shfl.sync.down.b32 btmp, bpart, 8, 31, fullmask;
        mov.b32 dot, btmp;
        add.rn.f32 part, part, dot;
        mov.b32 bpart, part;
        shfl.sync.down.b32 btmp, bpart, 4, 31, fullmask;
        mov.b32 dot, btmp;
        add.rn.f32 part, part, dot;
        mov.b32 bpart, part;
        shfl.sync.down.b32 btmp, bpart, 2, 31, fullmask;
        mov.b32 dot, btmp;
        add.rn.f32 part, part, dot;
        mov.b32 bpart, part;
        shfl.sync.down.b32 btmp, bpart, 1, 31, fullmask;
        mov.b32 dot, btmp;
        add.rn.f32 part, part, dot;
        // write per-warp sum
        setp.ne.u32 p0, lane, 0;
        @p0 bra SKIP_WARP_STORE_OP;
            mul.wide.u32 addr2, wid, 4;
            add.u64 addr2, sbase, addr2;
            st.shared.f32 [addr2], part;
    SKIP_WARP_STORE_OP:
        bar.sync 0;
        // cross-warp reduction by warp 0
        setp.ne.u32 p0, wid, 0;
        @p0 bra SKIP_CROSS_WARP_OP;
            setp.ge.u32 p1, lane, 8;
            @p1 mov.f32 dot, 0.0;
        @!p1 mul.wide.u32 addr2, lane, 4;
        @!p1 add.u64 addr2, sbase, addr2;
        @!p1 ld.shared.f32 dot, [addr2];
            mov.b32 bpart, dot;
        shfl.sync.down.b32 btmp, bpart, 4, 7, eightmask;
            mov.b32 part, btmp;
            add.rn.f32 dot, dot, part;
            mov.b32 bpart, dot;
        shfl.sync.down.b32 btmp, bpart, 2, 7, eightmask;
            mov.b32 part, btmp;
            add.rn.f32 dot, dot, part;
            mov.b32 bpart, dot;
        shfl.sync.down.b32 btmp, bpart, 1, 7, eightmask;
            mov.b32 part, btmp;
            add.rn.f32 dot, dot, part;
    SKIP_CROSS_WARP_OP:
        // thread 0 computes streaming softmax update and broadcasts alpha/beta
        setp.ne.u32 p0, tid, 0;
        @p0 bra AFTER_STREAM_UPDATE;
            mul.rn.f32 dot, dot, scale;            // s = dot * scale
            max.f32 part, maxv, dot;               // part = m_new
            sub.rn.f32 delta, maxv, part;          // m_old - m_new
            mul.rn.f32 delta, delta, invln2;
            ex2.approx.f32 kval, delta;            // kval = alpha
            sub.rn.f32 delta, dot, part;           // s - m_new
            mul.rn.f32 delta, delta, invln2;
            ex2.approx.f32 w, delta;               // w = beta
            fma.rn.f32 denom, denom, kval, w;      // l = l*alpha + beta
            mov.f32 maxv, part;                    // m = m_new
            // store alpha and beta at sbase+64, sbase+68
            mov.u64 addr2, sbase;
            add.u64 addr2, addr2, 64;
            st.shared.f32 [addr2], kval;           // alpha
            add.u64 addr2, addr2, 4;
            st.shared.f32 [addr2], w;              // beta
    AFTER_STREAM_UPDATE:
        bar.sync 0;
        // Load alpha and beta
        mov.u64 addr2, sbase;
        add.u64 addr2, addr2, 64;
        ld.shared.f32 part, [addr2];              // part = alpha
        add.u64 addr2, addr2, 4;
        ld.shared.f32 w, [addr2];                 // w = beta
        mov.f32 delta, part;                      // delta holds alpha for FMAs
        // V[j] row base
        add.u32 tmp32, base_bhS, j;
        mul.wide.u32 addr, tmp32, rD;
        shl.b64 addr, addr, 1;
        add.u64 addr, V, addr;
        // accumulate p = p*alpha + beta*V[j]
        setp.ge.u32 p0, d0, rD;
        @p0 bra P_V_SKIP0_OP;
            mul.wide.u32 addr2, d0, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            mul.rn.f32 out0, out0, delta;
            fma.rn.f32 out0, w, kval, out0;
    P_V_SKIP0_OP:
        setp.ge.u32 p0, d1, rD;
        @p0 bra P_V_SKIP1_OP;
            mul.wide.u32 addr2, d1, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            mul.rn.f32 out1, out1, delta;
            fma.rn.f32 out1, w, kval, out1;
    P_V_SKIP1_OP:
        setp.ge.u32 p0, d2, rD;
        @p0 bra P_V_SKIP2_OP;
            mul.wide.u32 addr2, d2, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            mul.rn.f32 out2, out2, delta;
            fma.rn.f32 out2, w, kval, out2;
    P_V_SKIP2_OP:
        setp.ge.u32 p0, d3, rD;
        @p0 bra P_V_SKIP3_OP;
            mul.wide.u32 addr2, d3, 2;
            add.u64 addr2, addr, addr2;
            ld.global.b16 hbits, [addr2];
            mov.b16 htmp, hbits;
            cvt.f32.f16 kval, htmp;
            mul.rn.f32 out3, out3, delta;
            fma.rn.f32 out3, w, kval, out3;
    P_V_SKIP3_OP:
         bar.sync 0;
        add.u32 j, j, 1;
        bra ONEPASS_J_LOOP;
    ONEPASS_DONE:
        // Broadcast final denom
        setp.ne.u32 p0, tid, 0;
        @p0 bra SKIP_STORE_DEN_FINAL;
             mov.u64 addr2, sbase;
             add.u64 addr2, addr2, 80;
             st.shared.f32 [addr2], denom;
     SKIP_STORE_DEN_FINAL:
         bar.sync 0;
         mov.u64 addr2, sbase;
         add.u64 addr2, addr2, 80;
         ld.shared.f32 denom, [addr2];
         // Write outputs normalized by denom
        setp.ge.u32 p0, d0, rD;
        @p0 bra STORE_SKIP0;
            div.rn.f32 out0, out0, denom;
            cvt.rn.f16.f32 htmp, out0;
            mul.wide.u32 addr2, d0, 2;
            add.u64 addr2, o_row_bytes, addr2;
            mov.b16 hbits, htmp;
            st.global.b16 [addr2], hbits;
    STORE_SKIP0:
        setp.ge.u32 p0, d1, rD;
        @p0 bra STORE_SKIP1;
            div.rn.f32 out1, out1, denom;
            cvt.rn.f16.f32 htmp, out1;
            mul.wide.u32 addr2, d1, 2;
            add.u64 addr2, o_row_bytes, addr2;
            mov.b16 hbits, htmp;
            st.global.b16 [addr2], hbits;
    STORE_SKIP1:
        setp.ge.u32 p0, d2, rD;
        @p0 bra STORE_SKIP2;
            div.rn.f32 out2, out2, denom;
            cvt.rn.f16.f32 htmp, out2;
            mul.wide.u32 addr2, d2, 2;
            add.u64 addr2, o_row_bytes, addr2;
            mov.b16 hbits, htmp;
            st.global.b16 [addr2], hbits;
    STORE_SKIP2:
        setp.ge.u32 p0, d3, rD;
        @p0 bra STORE_SKIP3;
            div.rn.f32 out3, out3, denom;
            cvt.rn.f16.f32 htmp, out3;
            mul.wide.u32 addr2, d3, 2;
            add.u64 addr2, o_row_bytes, addr2;
            mov.b16 hbits, htmp;
            st.global.b16 [addr2], hbits;
    STORE_SKIP3:
    DONE:
        ret;
    }
    """

# Ensure PTX is pure ASCII (ptxas requires 7-bit ASCII)
def _sanitize_ptx_ascii(s: str) -> str:
    repl = {
        '\u00b7': '*',   # middle dot
        '\u2013': '-',   # en dash
        '\u2014': '-',   # em dash
        '\u2212': '-',   # unicode minus
        '\u00a0': ' ',   # non-breaking space
    }
    return ''.join(repl.get(ch, ch) for ch in s)
PTX_SOURCE = _sanitize_ptx_ascii(PTX_SOURCE)
_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("sdp_attn_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.is_cuda and K.is_cuda and V.is_cuda
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16
        B, H, S, D = Q.shape
        out = torch.empty_like(Q)
        module = _get_ptx_module()
        module.launch(
            "sdp_attn_kernel",
            grid=(S, H, B),
            block=(256, 1, 1),
            arguments=[Q, K, V, out, i32(B), i32(H), i32(S), i32(D)],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

